// The watched-states 1.1 duty: the additive watched stamp on every serving
// route the task names — the scored listing (stamped from the batched facts
// the score already composed), the single-item GET (the route that composes
// no facts today gains the recsFactsFor composition), the sort=path opt-out
// (ledger set ALONE — rec_score stays absent, store order untouched), the
// per-series episode rows (composition gained, narrative order kept,
// unscored), and the progress rows under the scored default — plus the
// true-only omitempty semantics (field absent on the wire for unwatched
// rows). All asserted over the REAL router wiring and a real store, the
// repo's handler-test idiom (newRecsAPI + seedRecs* helpers).
func TestWatchedItemStamp(t *testing.T) {
	h, st, lib := newRecsAPI(t)
	ctx := context.Background()

	// Films: one ledgered, one not — their id order puts the unwatched one
	// first, so a sort=path stamp cannot be an order accident.
	plainFilm := seedRecsItem(t, st, lib, "wst_pf", "a-plain.mkv", map[string]any{}, time.Time{})
	watchedFilm := seedRecsItem(t, st, lib, "wst_wf", "b-watched.mkv", map[string]any{}, time.Time{})
	if err := st.InsertWatched(ctx, watchedFilm.ID, lib, "", time.Now().UTC()); err != nil {
		t.Fatalf("InsertWatched film: %v", err)
	}
	// A series with one ledgered and one fresh episode — the episode table
	// must split exactly on the ledger while keeping narrative order.
	show := seedRecsSeries(t, st, lib, "wshow", recsSeriesDoc("WShow"))
	epWatched := seedRecsItem(t, st, lib, "wst_e1", "wshow/e1.mkv", recsEpisodeDoc("wshow", ""), time.Time{})
	epFresh := seedRecsItem(t, st, lib, "wst_e2", "wshow/e2.mkv", recsEpisodeDoc("wshow", ""), time.Time{})
	if err := st.InsertWatched(ctx, epWatched.ID, lib, "wshow", time.Now().UTC()); err != nil {
		t.Fatalf("InsertWatched episode: %v", err)
	}
	// The progress surface: the watched episode's row keeps its positive
	// position beside the ledger row (the detector writes the ledger beside
	// the position), and the plain film carries an unwatched row — so the
	// scored default rail serves exactly one watched and one unwatched row.
	if _, err := st.PutProgress(ctx, epWatched.ID, 300); err != nil {
		t.Fatalf("PutProgress episode: %v", err)
	}
	if _, err := st.PutProgress(ctx, plainFilm.ID, 120); err != nil {
		t.Fatalf("PutProgress film: %v", err)
	}

	// stampRow is one surface row reduced to id + opaque DTO — item rows and
	// progress rows share it, so one table covers both wire shapes.
	type stampRow struct {
		id  string
		dto any
	}
	itemRows := func(t *testing.T, resp *http.Response) []stampRow {
		t.Helper()
		lr := decodeItems(t, resp)
		rows := make([]stampRow, len(lr.Items))
		for i, d := range lr.Items {
			rows[i] = stampRow{d.ID, d}
		}
		return rows
	}
	singleRow := func(t *testing.T, resp *http.Response) []stampRow {
		t.Helper()
		var ir itemResponse
		if err := json.NewDecoder(resp.Body).Decode(&ir); err != nil {
			t.Fatalf("decode itemResponse: %v", err)
		}
		return []stampRow{{ir.Item.ID, ir.Item}}
	}
	progressRows := func(t *testing.T, resp *http.Response) []stampRow {
		t.Helper()
		lr := decodeProgressList(t, resp)
		rows := make([]stampRow, len(lr.Items))
		for i, d := range lr.Items {
			rows[i] = stampRow{d.ItemID, d}
		}
		return rows
	}
	progressRow := func(t *testing.T, resp *http.Response) []stampRow {
		t.Helper()
		var d progressDTO
		if err := json.NewDecoder(resp.Body).Decode(&d); err != nil {
			t.Fatalf("decode progressDTO: %v", err)
		}
		return []stampRow{{d.ItemID, d}}
	}

	tcs := []struct {
		name     string
		url      string
		rows     func(t *testing.T, resp *http.Response) []stampRow
		watched  map[string]bool // id → watched must ride the wire; every served row not listed here must NOT carry it
		unscored bool            // rec_score must stay off EVERY row of the surface
		order    []string        // when non-nil, the exact served id order
	}{
		{
			name: "scored_listing_stamps_from_the_batched_facts",
			url:  "/api/v1/items?library=" + itoa64(lib),
			rows: itemRows,
			watched: map[string]bool{
				watchedFilm.ID: true,
				epWatched.ID:   true,
			},
		},
		{
			name:     "single_item_get_gains_the_composition",
			url:      "/api/v1/items/" + watchedFilm.ID,
			rows:     singleRow,
			watched:  map[string]bool{watchedFilm.ID: true},
			unscored: true, // the detail route never carries rec_score
		},
		{
			name:     "single_item_get_unwatched_absent",
			url:      "/api/v1/items/" + plainFilm.ID,
			rows:     singleRow,
			watched:  map[string]bool{},
			unscored: true,
		},
		{
			name:     "episode_rows_stamp_narrative_order_kept_unscored",
			url:      "/api/v1/series/" + show.ID + "/episodes",
			rows:     itemRows,
			watched:  map[string]bool{epWatched.ID: true},
			unscored: true,
			order:    []string{epWatched.ID, epFresh.ID},
		},
		{
			name: "sort_path_stamps_from_the_ledger_alone",
			url:  "/api/v1/items?library=" + itoa64(lib) + "&sort=path",
			rows: itemRows,
			watched: map[string]bool{
				watchedFilm.ID: true,
				epWatched.ID:   true,
			},
			unscored: true,
			// QueryItems' id-ordered SQL window, byte for byte — the stamp
			// must not have reordered it.
			order: []string{epWatched.ID, epFresh.ID, plainFilm.ID, watchedFilm.ID},
		},
		{
			// ?include=watched — since 1.3 the default listing withdraws the
			// ledgered episode's row, so its stamp is observable only on the
			// opt-in (TestProgressWatchedWithdrawal pins the withdrawal and
			// the 400 parse; the in-progress film's row stays unstamped).
			name: "progress_rows_stamp_under_include_watched",
			url:  "/api/v1/progress?include=watched",
			rows: progressRows,
			watched: map[string]bool{
				epWatched.ID: true,
			},
		},
		// The watched-states 1.6 duty: GET /progress/{item_id} — the ONE
		// serving route that still missed the stamp (D1's every-serving-route
		// law; no SPA consumer today, the wire is the contract). The handler
		// already composes the batched facts for the score, so the stamp is
		// the same facts.completed fold the scored list runs — pinned on both
		// wire sides: the ledgered episode's row stamps, the plain film's row
		// carries nothing (true-only omitempty). Unlike the listing, the
		// single GET serves the watched row regardless of ?include — the
		// withdrawal is a rail-page concern, never a per-record one.
		{
			name:    "single_progress_get_stamps_watched",
			url:     "/api/v1/progress/" + epWatched.ID,
			rows:    progressRow,
			watched: map[string]bool{epWatched.ID: true},
		},
		{
			name:    "single_progress_get_unwatched_absent",
			url:     "/api/v1/progress/" + plainFilm.ID,
			rows:    progressRow,
			watched: map[string]bool{},
		},
	}

	for _, tc := range tcs {
		t.Run(tc.name, func(t *testing.T) {
			resp := doRequest(t, h, http.MethodGet, tc.url, "", adminToken)
			defer resp.Body.Close()
			if resp.StatusCode != http.StatusOK {
				t.Fatalf("status = %d, want 200", resp.StatusCode)
			}
			rows := tc.rows(t, resp)
			if tc.order != nil {
				got := make([]string, len(rows))
				for i, r := range rows {
					got[i] = r.id
				}
				wantIDs(t, got, tc.order...)
			}
			for _, r := range rows {
				watched, recScore := wireWatchFlags(t, r.dto)
				if watched != tc.watched[r.id] {
					t.Fatalf("row %s: watched on wire = %v, want %v", r.id, watched, tc.watched[r.id])
				}
				if tc.unscored && recScore {
					t.Fatalf("row %s served rec_score — the surface must stay unscored", r.id)
				}
			}
		})
	}
}

// wireWatchFlags re-marshals one wire row and reports which of the additive
// watched-states fields rode it (the omitempty probes, as in the recs
// goldens' wireHasRecScore) — shared by both watched-stamp duties.
func wireWatchFlags(t *testing.T, d any) (watched, recScore bool) {
	t.Helper()
	b, err := json.Marshal(d)
	if err != nil {
		t.Fatalf("remarshal wire row: %v", err)
	}
	var wire map[string]any
	if err := json.Unmarshal(b, &wire); err != nil {
		t.Fatalf("unmarshal wire row: %v", err)
	}
	_, watched = wire["watched"]
	_, recScore = wire["rec_score"]
	return watched, recScore
}

// The watched-states 1.2 duty: the seriesDTO watched stamp — the
// all-episodes law derived in the scoreSeries walk, stamped on the scored
// list, the single-series GET (wire parity with the list row), and the
// sort=path branch (ledger set ALONE — rec_score stays absent, path order
// untouched). Fully-watched stamps true; a partially-watched or episode-less
// series stamps NOTHING (wire-absent, the true-only omitempty). Asserted
// over the REAL router wiring and a real store, the repo's handler-test
// idiom (newRecsAPI + seedRecs* helpers), the wire shape re-marshaled per
// row.
func TestWatchedSeriesStamp(t *testing.T) {
	h, st, lib := newRecsAPI(t)
	ctx := context.Background()

	// Three series seeded in alphabetical path order (wshow-e < wshow-f <
	// wshow-p), so no stamp can be an order accident: the fully-watched
	// series sits MID-LIST in path order yet must sink last under the scored
	// partition, and sort=path must keep the store order byte for byte.
	empty := seedRecsSeries(t, st, lib, "wshow-e", recsSeriesDoc("WEmpty"))
	full := seedRecsSeries(t, st, lib, "wshow-f", recsSeriesDoc("WFull"))
	part := seedRecsSeries(t, st, lib, "wshow-p", recsSeriesDoc("WPart"))

	// full: both episodes ledgered. part: one of two — the wire-absent half
	// of the law. empty: no episode rows at all (a series with zero episodes
	// is never watched). part's done episode starts the series and its fresh
	// sibling carries the new-episode bonus, so the scored default floats
	// part above the tag-less, score-zero empty series and sinks full last.
	for _, id := range []string{"wst_sf1", "wst_sf2"} {
		seedRecsItem(t, st, lib, id, "wshow-f/"+id+".mkv", recsEpisodeDoc("wshow-f", ""), time.Time{})
		if err := st.InsertWatched(ctx, id, lib, "wshow-f", time.Now().UTC()); err != nil {
			t.Fatalf("InsertWatched %s: %v", id, err)
		}
	}
	seedRecsItem(t, st, lib, "wst_sp1", "wshow-p/wst_sp1.mkv", recsEpisodeDoc("wshow-p", ""), time.Time{})
	seedRecsItem(t, st, lib, "wst_sp2", "wshow-p/wst_sp2.mkv", recsEpisodeDoc("wshow-p", ""), time.Time{})
	if err := st.InsertWatched(ctx, "wst_sp1", lib, "wshow-p", time.Now().UTC()); err != nil {
		t.Fatalf("InsertWatched wst_sp1: %v", err)
	}

	// stampRow is one surface row reduced to id + opaque DTO — list rows and
	// the single-series envelope share it, so one table covers both shapes.
	type stampRow struct {
		id  string
		dto any
	}
	listRows := func(t *testing.T, resp *http.Response) []stampRow {
		t.Helper()
		rows := decodeSeriesList(t, resp)
		out := make([]stampRow, len(rows))
		for i, d := range rows {
			out[i] = stampRow{d.ID, d}
		}
		return out
	}
	singleRows := func(t *testing.T, resp *http.Response) []stampRow {
		t.Helper()
		var sr seriesResponse
		if err := json.NewDecoder(resp.Body).Decode(&sr); err != nil {
			t.Fatalf("decode seriesResponse: %v", err)
		}
		return []stampRow{{sr.Series.ID, sr.Series}}
	}

	tcs := []struct {
		name     string
		url      string
		rows     func(t *testing.T, resp *http.Response) []stampRow
		watched  map[string]bool // id → watched must ride the wire; every served row not listed here must NOT carry it
		unscored bool            // rec_score must stay off EVERY row of the surface
		order    []string        // when non-nil, the exact served id order
	}{
		{
			name: "scored_list_stamps_from_the_score_walk",
			url:  "/api/v1/series?library=" + itoa64(lib),
			rows: listRows,
			watched: map[string]bool{
				full.ID: true,
			},
			// The partition reads the stamped field: the fully-watched
			// series sinks last even though path order puts it mid-list;
			// part's new-episode bonus floats it above the empty series.
			order: []string{part.ID, empty.ID, full.ID},
		},
		{
			name:     "single_get_fully_watched_true",
			url:      "/api/v1/series/" + full.ID,
			rows:     singleRows,
			watched:  map[string]bool{full.ID: true},
			unscored: true, // the detail route never carries rec_score
		},
		{
			name:     "single_get_partially_watched_absent",
			url:      "/api/v1/series/" + part.ID,
			rows:     singleRows,
			watched:  map[string]bool{},
			unscored: true,
		},
		{
			name:     "single_get_zero_episode_series_absent",
			url:      "/api/v1/series/" + empty.ID,
			rows:     singleRows,
			watched:  map[string]bool{},
			unscored: true,
		},
		{
			name:     "sort_path_stamps_from_the_ledger_alone",
			url:      "/api/v1/series?library=" + itoa64(lib) + "&sort=path",
			rows:     listRows,
			watched:  map[string]bool{full.ID: true},
			unscored: true,
			// QuerySeries' relative_path order, byte for byte — the stamp
			// must not have reordered it (and no rec_score rides it).
			order: []string{empty.ID, full.ID, part.ID},
		},
	}

	for _, tc := range tcs {
		t.Run(tc.name, func(t *testing.T) {
			resp := doRequest(t, h, http.MethodGet, tc.url, "", adminToken)
			defer resp.Body.Close()
			if resp.StatusCode != http.StatusOK {
				t.Fatalf("status = %d, want 200", resp.StatusCode)
			}
			rows := tc.rows(t, resp)
			if tc.order != nil {
				got := make([]string, len(rows))
				for i, r := range rows {
					got[i] = r.id
				}
				wantIDs(t, got, tc.order...)
			}
			for _, r := range rows {
				watched, recScore := wireWatchFlags(t, r.dto)
				if watched != tc.watched[r.id] {
					t.Fatalf("row %s: watched on wire = %v, want %v", r.id, watched, tc.watched[r.id])
				}
				if tc.unscored && recScore {
					t.Fatalf("row %s served rec_score — the surface must stay unscored", r.id)
				}
			}
		})
	}
}

// The watched-states 1.3 duty: the continue surface's withdrawal default —
// rows whose item is ledgered drop from BOTH branches (the scored default AND
// the sort=recent opt-out, which gains the batched ledger read it makes none
// of today), ?include=watched restores them stamped watched: true, an unknown
// include value is 400 (parseSort's strict-parse posture), and the
// in-progress rows never move — exact order asserted per branch. Asserted
// over the REAL router wiring and a real store, the repo's handler-test idiom.
func TestProgressWatchedWithdrawal(t *testing.T) {
	h, st, lib := newRecsAPI(t)
	ctx := context.Background()

	// Three films, positions written old → new: two in-progress and one
	// completed watch whose positive position stays beside its ledger row
	// (the detector writes the ledger beside the position). All score the
	// same 1000 tier (no tags — pure resume bonus), so the scored default's
	// tie break is recency: any order shift would be a withdrawal bug, not a
	// scoring accident.
	older := seedRecsItem(t, st, lib, "pww_o", "pww-o.mkv", map[string]any{}, time.Time{})
	done := seedRecsItem(t, st, lib, "pww_d", "pww-d.mkv", map[string]any{}, time.Time{})
	newer := seedRecsItem(t, st, lib, "pww_n", "pww-n.mkv", map[string]any{}, time.Time{})
	if err := st.InsertWatched(ctx, done.ID, lib, "", time.Now().UTC()); err != nil {
		t.Fatalf("InsertWatched: %v", err)
	}
	for _, p := range []struct {
		id  string
		pos int64
	}{
		{older.ID, 100},
		{done.ID, 100},
		{newer.ID, 100},
	} {
		if _, err := st.PutProgress(ctx, p.id, p.pos); err != nil {
			t.Fatalf("PutProgress %s: %v", p.id, err)
		}
		time.Sleep(2 * time.Millisecond)
	}

	served := func(t *testing.T, url string) []progressDTO {
		t.Helper()
		resp := doRequest(t, h, http.MethodGet, url, "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("%s: status = %d, want 200", url, resp.StatusCode)
		}
		return decodeProgressList(t, resp).Items
	}
	ids := func(rows []progressDTO) []string {
		out := make([]string, len(rows))
		for i, d := range rows {
			out[i] = d.ItemID
		}
		return out
	}

	t.Run("default_withdraws_in_both_branches", func(t *testing.T) {
		// Both branches drop the ledgered row; the in-progress rows keep
		// their branch order (score-desc/recency, and the store's recency
		// window respectively) — withdrawal never reorders.
		wantIDs(t, ids(served(t, "/api/v1/progress")), newer.ID, older.ID)
		wantIDs(t, ids(served(t, "/api/v1/progress?sort=recent")), newer.ID, older.ID)
	})

	t.Run("include_watched_restores_stamped", func(t *testing.T) {
		// The opt-in restores the completed watch in BOTH branches, carrying
		// watched: true on the wire; the in-progress rows stay unstamped
		// (true-only omitempty). The branches place it differently: the
		// scored default has no resume bonus for a completed watch
		// (inProgress = hasProgress && !completed — its tags-only score
		// sinks it last), while sort=recent is pure store recency.
		for _, tc := range []struct {
			url   string
			order []string
		}{
			{"/api/v1/progress?include=watched", []string{newer.ID, older.ID, done.ID}},
			{"/api/v1/progress?sort=recent&include=watched", []string{newer.ID, done.ID, older.ID}},
		} {
			rows := served(t, tc.url)
			wantIDs(t, ids(rows), tc.order...)
			for _, d := range rows {
				watched, _ := wireWatchFlags(t, d)
				if want := d.ItemID == done.ID; watched != want {
					t.Fatalf("%s: row %s watched on wire = %v, want %v", tc.url, d.ItemID, watched, want)
				}
			}
		}
	})

	t.Run("unknown_include_is_400_both_branches", func(t *testing.T) {
		for _, url := range []string{
			"/api/v1/progress?include=recent",
			"/api/v1/progress?sort=recent&include=none",
		} {
			resp := doRequest(t, h, http.MethodGet, url, "", adminToken)
			defer resp.Body.Close()
			if resp.StatusCode != http.StatusBadRequest {
				t.Fatalf("%s: status = %d, want 400", url, resp.StatusCode)
			}
		}
	})

	t.Run("scored_default_stays_scored", func(t *testing.T) {
		// The withdrawal must not unscore the surface: rec_score still rides
		// the scored default's rows.
		for _, d := range served(t, "/api/v1/progress") {
			if _, has := progressWireScore(t, d); !has {
				t.Fatalf("scored row %s omitted rec_score", d.ItemID)
			}
		}
	})
}
